    public void Gold_customer_gets_five_percent_off_a_50_dollar_subtotal()
    {
        Assert.Equal(4_750, _useCase.For(5_000, LoyaltyTier.Gold));
    }

    [Fact]
    public void Gold_customer_pays_nothing_for_an_empty_subtotal()
    {
        Assert.Equal(0, _useCase.For(0, LoyaltyTier.Gold));
    }
}
